<script lang="ts">
import {onMount} from 'svelte';import type {Catalog} from './locales';
let {t,request,installAllowed,onchanged=()=>{},autoCheck=true}=$props<{t:Catalog;request:(url:string,body?:object)=>Promise<any>;installAllowed:boolean;onchanged?:()=>void;autoCheck?:boolean}>();let signature='';function notify(){const s=[info?.current,info?.latest,info?.available,info?.job?.state].join('|');if(signature&&s!==signature)onchanged();signature=s;}
type Info={current:string;latest:string|null;available:boolean;canInstall:boolean;releaseUrl:string|null;job:{id:string;state:string;phase:string;bytes:number;total:number;error?:string}|null};
let info=$state<Info|null>(null),busy=$state(false),error=$state(''),restarting=$state(localStorage.getItem('replay.update.pending')==='true');let dialog:HTMLDialogElement;
let active=$derived(['downloading','verifying','applying'].includes(info?.job?.state??''));
async function load(){try{info=await request('/api/updates');notify();if(restarting&&info?.job?.state!=='applying'){restarting=false;localStorage.removeItem('replay.update.pending');}}catch(e){if(!restarting)error=(e as Error).message;}}
async function action(name:string){busy=true;error='';try{info=await request('/api/updates/'+name,{});notify();if(name==='apply'){restarting=true;localStorage.setItem('replay.update.pending','true');}}catch(e){error=(e as Error).message;}finally{busy=false;}}
onMount(()=>{load().then(()=>{if(autoCheck&&!info?.latest&&!active&&!restarting)action("check");});const timer=setInterval(load,2000);return()=>clearInterval(timer);});
</script>
<section class="update-panel" aria-label={t.updates}><div class="update-heading"><h2>{t.updates}</h2><button disabled={busy||active||restarting} onclick={()=>action('check')}>{t.checkUpdates}</button></div><div class="version-row"><span>{t.currentVersion}: <strong>{info?.current??'—'}</strong></span><span>{t.latestVersion}: <strong>{info?.latest??'—'}</strong></span>{#if info?.releaseUrl}<a href={info.releaseUrl} target="_blank" rel="noopener noreferrer">{t.releaseNotes} ↗</a>{/if}</div><p class="muted">{t.updateHint}</p>{#if info&&!info.canInstall}<p class="muted">{t.updateDocker}</p>{:else}<div class="actions"><button disabled={busy||active||!info?.available||!installAllowed||info?.job?.state==='ready'} onclick={()=>action('download')}>{t.updateDownload}</button><button class="primary" disabled={busy||!installAllowed||info?.job?.state!=='ready'} onclick={()=>dialog.showModal()}>{t.updateInstall}</button>{#if ['downloading','verifying','ready'].includes(info?.job?.state??'')}<button disabled={busy} onclick={()=>action('cancel')}>{t.cancel}</button>{/if}</div>{/if}
<p class="update-status" role="status">{restarting||info?.job?.state==='applying'?t.updateReconnecting:info?.job?.state==='failed'?t.updateFailed:info?.job?.state==='ready'?t.updateReady:info?.job?.state==='completed'?t.updateCompleted:info?.job?.state==='downloading'?t.updateDownloading:info?.job?.state==='verifying'?t.updateVerifying:info?.job?.state==='cancelled'?t.updateCancelled:info?.available?t.updateAvailable:info?.latest?t.updateCurrent:t.updateUnk}</p>{#if info?.job?.state==='downloading'}<progress max={info.job.total||1} value={info.job.bytes} aria-label={t.updateDownloading}></progress>{/if}{#if error||info?.job?.error}<p class="error" role="alert">{t.errors[(error||info?.job?.error) as keyof typeof t.errors]??t.errors['request.failed']}</p>{/if}</section>
<dialog bind:this={dialog} aria-labelledby="update-confirm-title"><h2 id="update-confirm-title">{t.updateTitle}</h2><p>{t.updateConfirm}</p><div class="actions"><button onclick={()=>dialog.close()}>{t.cancel}</button><button class="primary" onclick={()=>{dialog.close();action('apply');}}>{t.updateInstall}</button></div></dialog>
